"""RoboPaint reference study. All painting is through the standard robot client."""
import json,time,sys,os
import numpy as np
from PIL import Image
sys.path.insert(0,'/opt/tools')
from rcb_client import Robot
OUT='/app/output'
r=Robot()
spec=r.spec()
Q=[0.,1.,0.,0.]

def submit(a,note=''):
    a=np.asarray(a,dtype=float)
    for i in range(0,len(a),190):
        before=r.status()
        np.save(f'{OUT}/pending.npy',a[i:i+190])
        try: res=r.submit('ee_pose',a[i:i+190],dt=.05,cameras=[],video='none',note=note)
        except Exception:
            st=r.wait_ready();print('RESUMED',st,flush=True)
            if st['control_steps']==before['control_steps']: res=r.submit('ee_pose',a[i:i+190],dt=.05,cameras=[],video='none',note=note)
            else: raise
        with open(f'{OUT}/motion.jsonl','a') as f:f.write(json.dumps({'note':note,'a':a[i:i+190].tolist(),'meta':res.meta})+'\n')
        if res.stopped: raise RuntimeError('Partial submit')
        if res.meta.get('plan'): print('plan',res.meta['plan'],flush=True)
    return res

def move(points,speed=.1,hold=.25):
    o=r.get_obs(cameras=[]);pos=np.array(o.meta['proprio']['now'][7:10]);a=[]
    for p in points:
        p=np.array(p); n=max(1,int(np.ceil(np.linalg.norm(p-pos)/speed/.05)))
        a.extend([list(v)+Q for v in np.linspace(pos,p,n+1)[1:]])
        a.extend([list(p)+Q]*round(hold/.05));pos=p
    return submit(a,'move')

def observe(name):
    o=r.get_obs(cameras=['canvas_cam','practice_cam','scene_cam','side_cam'],depth=True)
    o.save(f'{OUT}/{name}')
    for c,im in o.last.items():Image.fromarray(im).save(f'{OUT}/{name}_{c}.png')
    return o

if __name__=='__main__':
    if sys.argv[1]=='park':
        move([[-.28,0,.15]],.1);observe('park')
